    preds_a = np.array([s["pred"] for s in stats_a])
    tps_b = np.array([s["tp"] for s in stats_b])
    golds_b = np.array([s["gold"] for s in stats_b])
    preds_b = np.array([s["pred"] for s in stats_b])

    indices = rng.randint(0, n, size=(n_bootstrap, n))

    f1_a = _f1_from_arrays(tps_a[indices].sum(axis=1).astype(float),
